<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\SupportTicket;use Illuminate\Http\Request;
class SupportTicketController extends Controller {public function index(Request $r){$u=$r->user();return ['success'=>true,'data'=>SupportTicket::where('project_id',$u->project_id)->where('user_id',$u->id)->latest()->get()];}public function store(Request $r){$d=$r->validate(['ticket_type'=>'required|string|max:80','requested_by'=>'required|string|max:150','position'=>'nullable|string|max:100','email'=>'required|email','phone'=>'nullable|string|max:40','subject'=>'required|string|max:255','description'=>'required|string','priority'=>'required|in:Normal,High','confidential'=>'boolean']);$u=$r->user();$n=SupportTicket::where('project_id',$u->project_id)->count()+1;$t=SupportTicket::create($d+['project_id'=>$u->project_id,'user_id'=>$u->id,'ticket_no'=>'SUP-'.now()->format('Y').'-'.str_pad((string)$n,4,'0',STR_PAD_LEFT),'status'=>'New Ticket']);return response()->json(['success'=>true,'data'=>$t,'message'=>'Support ticket submitted.'],201);}public function show(Request $r,SupportTicket $ticket){abort_unless((int)$ticket->project_id===(int)$r->user()->project_id&&(int)$ticket->user_id===(int)$r->user()->id,404);return ['success'=>true,'data'=>$ticket];}}
